<div class="row g-3"><div class="col-md-6"><label class="form-label" for="name">Full name</label><input class="form-control" id="name" name="name" value="{{ old('name', $patient->name ?? '') }}" required></div><div class="col-md-6"><label class="form-label" for="email">Email address</label><input class="form-control" id="email" type="email" name="email" value="{{ old('email', $patient->email ?? '') }}" required></div><div class="col-md-6"><label class="form-label" for="password">{{ isset($patient) ? 'New password (optional)' : 'Password' }}</label><input class="form-control" id="password" type="password" name="password" @unless(isset($patient)) required @endunless></div><div class="col-md-6"><label class="form-label" for="password_confirmation">Confirm password</label><input class="form-control" id="password_confirmation" type="password" name="password_confirmation"></div></div>
